import {useNavigation, useRoute} from '@react-navigation/native';
import {isEmpty, isUndefined} from 'lodash';
import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {TouchableOpacity, View} from 'react-native';
import {SafeAreaView} from 'react-native-safe-area-context';
import ListGeneralInfoDocument from '../document-detail/components/ListGeneralInforDocument';
import ModalConfirmUpdateValidity from './components/ModalConfirmUpdateValidity';
import ModalCreateBatch from './components/ModalCreateBatch';
import ModalUpdateValidity from './components/ModalUpdateValidity';
import {
  ActionItem,
  ActionType,
  getListAction,
  handleDownloadUrlDocumentTemplate,
} from './helper';
import styles from './styles';
import {
  IDocument,
  IDocumentTemplate,
  IFieldsByHeader,
  StatusDocumentTemplate,
} from '../../../model/interface/envelope.interface';
import {useDocumentStore} from '../../../navigation/SideMenu/store/app-store';
import useFileDownloader from '../../../hook/useFileDownloader';
import TextCM from '../../../components/Text';
import {
  IconBlackUserCreate,
  IconBluePublished,
  IconBlueUnpublished,
  IconCreateDate,
  IconGreenPublish,
  IconParties,
  IconRedUnpublished,
} from '../../../assets/images';
import HeaderCM from '../../../components/Header/HeaderCM';
import {ItemType} from '../../../navigation/SideMenu/components/CustomDrawerContent/helper';
import {DateUtils} from '../../../utils';
import ModalConfirm from '../../../components/ModalConfirm';
import {NavigationName} from '../../../constants';
import {useDocumentServices} from '../../../hook/apiHook/useApi';
import Toast from 'react-native-toast-message';
import useCreateBatchStore from '../store/createBatchStore';

const DocumentTemplateDetail = () => {
  const navigation = useNavigation<any>();
  const route = useRoute<any>();
  const dataRoute: IDocumentTemplate = route.params.data;
  const [data, setData] = useState<IDocumentTemplate>(dataRoute);
  const [dataGeneralInfor, setDataGeneralInfor] = useState<IFieldsByHeader[]>(
    [],
  );

  const {currentFocused, reloadDataFn} = useDocumentStore();

  const [modalUnpublished, setModalUnpublished] = useState(false);
  const [modalValidity, setModalValidity] = useState(false);
  const [modalCreateBatch, setModalCreateBatch] = useState(false);
  const [dataConfirm, setDataConfirm] = useState<
    IDocumentTemplate[] | undefined
  >();
  const [showModalConfirm, setShowModalConfirm] = useState(false);

  const {t} = useTranslation();

  const DocumentServices = useDocumentServices();
  const {updateDataTemplate} = useCreateBatchStore();

  const toggleModalConfirm = () => {
    setShowModalConfirm(!showModalConfirm);
  };

  const {onDownloadStart} = useFileDownloader(
    `${data.id}.zip`,
    handleDownloadUrlDocumentTemplate(data.id),
  );

  useEffect(() => {
    getDetailById();
  }, []);

  const getDetailById = async () => {
    try {
      // dispatch(commonActions.setLoading(true));
      const res = await DocumentServices.getTemplateDetailById({id: data.id});
      // setTimeout(() => {
      //   dispatch(commonActions.setLoading(false));
      // }, 500);
      setData({...res, type: dataRoute.type});
      let newRes = {...res, type: dataRoute.type} as unknown as IDocument;
      let dataDisable = newRes.header.fields.filter(
        item =>
          item.id !== 'envSubmittedFrom' &&
          item.id !== 'envName' &&
          item.type !== 'Base64',
      );
      setDataGeneralInfor(
        dataDisable.filter(item => {
          if (isEmpty(item.value) || isUndefined(item.value)) {
            return null;
          } else {
            return item;
          }
        }),
      );
    } catch (error) {}
  };

  const toggleModalUnpublished = () => {
    setModalUnpublished(!modalUnpublished);
  };

  const toggleModalValidity = () => {
    setModalValidity(!modalValidity);
  };

  const toggleModalCreateBatch = () => {
    setModalCreateBatch(!modalCreateBatch);
  };

  const handleGetUrlContract = async () => {
    try {
      navigation.navigate(NavigationName.PDFViewScreen, {
        id: data.id,
        documentId: data?.documents?.[0]?.id,
      });
    } catch (error) {}
  };

  const onPressAction = (type: ActionType) => {
    switch (type) {
      case ActionType.open:
        handleGetUrlContract();
        //Mở tài liệu:
        break;
      case ActionType.createSingle:
        //Tạo tài liệu đơn:
        navigation.navigate(NavigationName.GeneralInfomationScreen, {data});
        break;
      case ActionType.createBatch:
        //Tạo tài liệu hàng loạt:
        updateDataTemplate(data);
        toggleModalCreateBatch();
        break;
      case ActionType.validity:
        toggleModalValidity();
        break;
      case ActionType.history:
        navigation.navigate(NavigationName.DocumentTemplateHistoryScreen, {
          data,
        });
        break;
      case ActionType.download:
        //Tải về tài liệu:
        onDownloadStart();
        break;
      case ActionType.share:
        navigation.navigate(NavigationName.DocumentShareScreen, {data});
        break;
      case ActionType.disable:
        toggleModalUnpublished();
        break;
      default:
        break;
    }
  };

  const renderItemAction = (item: ActionItem) => {
    return (
      <TouchableOpacity
        style={styles.btnAction}
        key={item.type}
        onPress={() => onPressAction(item.type)}>
        <View style={styles.viewIcon}>{item.icon}</View>
        <TextCM style={styles.txtNameAction}>{item.name}</TextCM>
      </TouchableOpacity>
    );
  };

  const renderIconModalUnpublished = () => {
    if (data.status === StatusDocumentTemplate.published) {
      return <IconRedUnpublished width={80} height={78} />;
    }
    return <IconGreenPublish width={80} height={78} />;
  };

  const onUnpublishedDocument = async () => {
    toggleModalUnpublished();
    const body = {
      ...data,
      status:
        data.status === StatusDocumentTemplate.published
          ? StatusDocumentTemplate.unpublished
          : StatusDocumentTemplate.published,
    };
    try {
      const res = await DocumentServices.saveDocumentTemplate(body);
      if (res.status === 202) {
        setDataConfirm(res.data as IDocumentTemplate[]);
        toggleModalConfirm();
        return;
      }
      setData({...res.data, type: dataRoute.type} as any);
      toastSuccess();
      reloadDataFn();
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('eContract.CM.TxtSystemError'),
      });
    }
  };

  const toastSuccess = () => {
    Toast.show({
      type: 'success',
      text1: t('eContract.DC.DocumentTemplate.TxtUpdateSuccess'),
    });
  };

  const checkExpDate = () => {
    if (data.effDate) {
      const currentDate = Date.now();
      const expDate = new Date(data.expDate).getTime();
      return currentDate > expDate;
    }
    return true;
  };

  const refactorListAction = () => {
    const list = getListAction(data);
    return list.filter(item => {
      if (
        item.type === ActionType.createBatch ||
        item.type === ActionType.createSingle
      ) {
        if (checkExpDate()) return false;
      }
      return true;
    });
  };

  const onUpdateSuccess = () => {
    getDetailById();
    reloadDataFn();
  };

  return (
    <SafeAreaView
      edges={['bottom']}
      style={[
        styles.ctnMain,
        {backgroundColor: dataGeneralInfor?.length > 0 ? '#FFF' : '#F1F1F1'},
      ]}>
      <HeaderCM title={t('eContract.DC.DocumentTemplate.TxtDocumentTemplateDetail')} />
      <View style={styles.contain}>
        <View style={styles.body}>
          <View style={styles.viewTitle}>
            {data.status === StatusDocumentTemplate.published ? (
              <IconBlueUnpublished width={20} height={24} />
            ) : (
              <IconBluePublished width={17} height={24} />
            )}
            <TextCM
              style={[
                styles.txtTitle,
                data.status === StatusDocumentTemplate.unpublished &&
                  styles.txtTitleUnpublished,
              ]}>
              {data.name?.trim()}
            </TextCM>
          </View>

          <View style={styles.viewList}>
            {currentFocused === ItemType.TemplateShare && (
              <View style={styles.viewItem}>
                <View style={styles.viewName}>
                  <IconBlackUserCreate width={18} height={17} />
                  <TextCM style={styles.txtName}>
                    {t('eContract.DC.TxtUserCreate')}
                  </TextCM>
                </View>
                <TextCM style={styles.txtValue}>{data.createdBy}</TextCM>
              </View>
            )}

            <View style={styles.viewItem}>
              <View style={styles.viewName}>
                <IconCreateDate width={18} height={17} />
                <TextCM style={styles.txtName}>
                  {t('eContract.DC.DocumentTemplate.TxtEffectFrom')}
                </TextCM>
              </View>
              <TextCM style={styles.txtValue}>
                {DateUtils.convertDateToDDMMYYYY(data.effDate)}
              </TextCM>
            </View>

            <View style={styles.viewItem}>
              <View style={styles.viewName}>
                <IconCreateDate width={18} height={17} />
                <TextCM style={styles.txtName}>
                  {t('eContract.DC.DocumentTemplate.TxtEffectTo')}
                </TextCM>
              </View>
              <TextCM style={styles.txtValue}>
                {DateUtils.convertDateToDDMMYYYY(data.expDate)}
              </TextCM>
            </View>

            <View style={styles.viewItem}>
              <View style={styles.viewName}>
                <IconParties width={18} height={17} />
                <TextCM style={styles.txtName}>{t('eContract.DC.TxtParties')}</TextCM>
              </View>
              <View style={styles.viewValueParties}>
                {!isEmpty(data?.parties) ? (
                  data?.parties?.map((item: any) => {
                    return (
                      <TextCM style={styles.txtValue} key={item.id}>
                        {item.type !== 'individual'
                          ? item.name || '---'
                          : item.recipients?.[0]?.contact?.name}
                      </TextCM>
                    );
                  })
                ) : (
                  <TextCM style={styles.txtValue}>---</TextCM>
                )}
              </View>
            </View>
          </View>
        </View>
        <View style={styles.action}>
          {refactorListAction()?.map(item => renderItemAction(item))}
        </View>
      </View>
      {dataGeneralInfor?.length > 0 && (
        <ListGeneralInfoDocument data={dataGeneralInfor} dataEkyc={[]} />
      )}

      <ModalConfirm
        content={
          data.status === StatusDocumentTemplate.published
            ? t('eContract.DC.DocumentTemplate.TxtConfirmUnpublished')
            : t('eContract.DC.DocumentTemplate.TxtConfirmPublished')
        }
        title={
          data.status === StatusDocumentTemplate.published
            ? t('eContract.DC.DocumentTemplate.TxtUnpublished')
            : t('eContract.DC.DocumentTemplate.TxtPublished')
        }
        onClose={toggleModalUnpublished}
        isVisible={modalUnpublished}
        renderIcon={renderIconModalUnpublished}
        onConfirm={onUnpublishedDocument}
      />
      {modalValidity && (
        <ModalUpdateValidity
          isVisible={modalValidity}
          toggleModal={toggleModalValidity}
          data={data}
          onUpdateSuccess={onUpdateSuccess}
        />
      )}
      {modalCreateBatch && (
        <ModalCreateBatch
          isVisible={modalCreateBatch}
          toggleModal={toggleModalCreateBatch}
        />
      )}
      {!isEmpty(dataConfirm) && (
        <ModalConfirmUpdateValidity
          isVisible={showModalConfirm}
          toggleModal={toggleModalConfirm}
          data={dataConfirm}
          onUpdateSuccess={() => {
            toastSuccess();
            onUpdateSuccess();
          }}
        />
      )}
    </SafeAreaView>
  );
};

export default DocumentTemplateDetail;
