import {debounce, isEmpty} from 'lodash';
import React, {useEffect, useRef, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {FlatList, RefreshControl, View} from 'react-native';
import InputSearch from '../document-list/components/InputSearch';
import DocumentTemplateItem from './components/DocumentTemplateItem';
import ModalFilter from './components/ModalFilter';
import {getPathApi, getTitleTemplate} from './helper';
import styles from './styles';
import {useDocumentStore} from '../../../navigation/SideMenu/store/app-store';
import {
  IDocumentTemplate,
  StatusDocumentTemplate,
} from '../../../model/interface/envelope.interface';
import HeaderCM from '../../../components/Header/HeaderCM';
import TextCM from '../../../components/Text';
import {useDocumentServices} from '../../../hook/apiHook/useApi';

const DocumentTemplate = () => {
  const {t} = useTranslation();
  const currentFocused = useDocumentStore(state => state.currentFocused);
  const reloadData = useDocumentStore(state => state.reloadData);

  const [searchText, setSearchText] = useState('');
  const [debouncedSearchText, setDebouncedSearchText] = useState('');
  const [data, setData] = useState<IDocumentTemplate[]>([]);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [isShowFilter, setIsShowFilter] = useState(false);
  const [filterData, setFilterData] = useState<any>({});

  const refFlatList = useRef<any>();

  const DocumentServices = useDocumentServices();

  const debouncedSearch = debounce((text: string) => {
    setDebouncedSearchText(text);
  }, 300);

  useEffect(() => {
    debouncedSearch(searchText);
    return () => {
      debouncedSearch.cancel();
    };
  }, [searchText]);

  useEffect(() => {
    getData(debouncedSearchText, filterData);
  }, [currentFocused, debouncedSearchText, filterData, reloadData]);

  useEffect(() => {
    if (!isEmpty(filterData) || searchText) {
      resetData();
    }
    if (data.length > 0) {
      refFlatList.current?.scrollToOffset({animated: true, offset: 0});
    }
  }, [currentFocused]);

  const resetData = () => {
    setSearchText('');
    setDebouncedSearchText('');
    setFilterData({});
  };

  const getData = async (
    keyWord = '',
    filterData?: {sort: string} | undefined,
  ) => {
    const pathApt = getPathApi(currentFocused);
    const params: {page: number; size: number; sort?: string} = {
      page: 0,
      size: 1000,
    };
    if (filterData?.sort || pathApt?.params?.sort) {
      params.sort = filterData?.sort || pathApt?.params?.sort;
    }

    const data = await DocumentServices.getDatTemplate(pathApt.path, params);
    const dataSort = data.sort(
      (a: any, b: any) =>
        new Date(b?.lastModifiedDate).getTime() -
        new Date(a?.lastModifiedDate).getTime(),
    );
    const dataPublished = dataSort.filter(
      (item: any) => item.status === StatusDocumentTemplate.published,
    );
    const dataUnpublished = dataSort.filter(
      (item: any) => item.status === StatusDocumentTemplate.unpublished,
    );
    const newData = [...dataPublished, ...dataUnpublished];
    const filteredData = newData.filter(item =>
      item.name.toLowerCase().includes(keyWord.toLowerCase().trim()),
    );
    setData(filteredData);
    setIsRefreshing(false);
  };

  const renderItem = ({item}: {item: IDocumentTemplate}) => {
    return <DocumentTemplateItem data={item} />;
  };

  const onRefresh = async () => {
    setIsRefreshing(true);
    getData(debouncedSearchText, filterData);
  };

  const toggleShowFilter = () => {
    setIsShowFilter(!isShowFilter);
  };

  const onFilter = (data: any) => {
    setFilterData(data);
  };

  return (
    <View style={styles.ctnMain}>
      <HeaderCM
        title={t(getTitleTemplate(currentFocused))}
        // isShowIconLeft={false}
        // containerStyle={styles.header}
      />
      <InputSearch
        setSearchText={setSearchText}
        searchText={searchText}
        onPressFilter={toggleShowFilter}
      />
      <FlatList
        data={data}
        ref={refFlatList}
        keyExtractor={item => item.id}
        renderItem={renderItem}
        contentContainerStyle={styles.body}
        refreshControl={
          <RefreshControl refreshing={isRefreshing} onRefresh={onRefresh} />
        }
        ListEmptyComponent={<Nodata />}
      />
      <ModalFilter
        onFilter={onFilter}
        isShowFilter={isShowFilter}
        toggleShowFilter={toggleShowFilter}
        filterData={filterData}
      />
    </View>
  );
};

export default DocumentTemplate;

const Nodata = () => {
  const {t} = useTranslation();
  return (
    <TextCM style={styles.txtNoData}>{t('eContract.DC.TxtNoData')}</TextCM>
  );
};
