import {View, Text, ScrollView} from 'react-native';
import React from 'react';
import styles from './styles';
import {useTranslation} from 'react-i18next';
import {SafeAreaView} from 'react-native-safe-area-context';
import Information from './components/Information';
import AccountDetail from './components/AccountDetail';
import OrganizationInfo from './components/OrganizationInfo';
import SignatureInfo from './components/SignatureInfo';
import {useFocusEffect} from '@react-navigation/native';
import { useAppDispatch } from '../../hook/useRedux';
import { accountActions } from '../../redux/slices';
import HeaderCM from '../../components/Header/HeaderCM';

const AccountInfo = () => {
  const {t} = useTranslation();
  const dispatch = useAppDispatch();

  useFocusEffect(
    React.useCallback(() => {
      getData();
    }, []),
  );

  const getData = async () => {
    dispatch(accountActions.fetchAccount());
  };

  return (
    <SafeAreaView edges={['bottom']} style={styles.ctnMain}>
      <HeaderCM title={t('eContract.AI.TxtAccountInfo')} />
      <ScrollView
        keyboardShouldPersistTaps="handled"
        style={styles.mainContainer}>
        <Information />
        <AccountDetail />
        <OrganizationInfo />
        <SignatureInfo />
      </ScrollView>
    </SafeAreaView>
  );
};

export default AccountInfo;
