import {isNull, isUndefined} from 'lodash';
import {
  EnvelopeStatus,
  StatusNotification,
} from '../../../model/interface/notification.interface';
import {ActionType} from '../../../model/enum/enum';
import {
  IconBlueFile,
  IconPriority,
  IconAuthority,
  IconForward,
  IconRedPriorityNoti,
  IconBluePriorityNoti,
  IconGreenPriorityNoti,
} from '../../../assets/images';

export const getListActionNotification = (
  type: StatusNotification | EnvelopeStatus,
  typeEnvelop?: StatusNotification | EnvelopeStatus,
) => {
  if (
    type === StatusNotification.processing &&
    (typeEnvelop === StatusNotification.accepted ||
      typeEnvelop === StatusNotification.forwarded ||
      typeEnvelop === StatusNotification.delegated)
  ) {
    return [
      {
        name: 'eContract.NT.TxtOpenDocument',
        icon: <IconBlueFile width={14} height={18} />,
        type: ActionType.open,
      },
      {
        name: 'eContract.NT.TxtHistory',
        icon: <IconBlueFile width={14} height={18} />,
        type: ActionType.history,
      },
    ];
  }
  switch (type) {
    case StatusNotification.voided:
    case StatusNotification.completed:
    case StatusNotification.accepted:
    case StatusNotification.delegated:
    case StatusNotification.forwarded:
    case StatusNotification.rejected:
    case StatusNotification.overdue:
      return [
        {
          name: 'eContract.NT.TxtOpenDocument',
          icon: <IconBlueFile width={14} height={18} />,
          type: ActionType.open,
        },
        {
          name: 'eContract.NT.TxtHistory',
          icon: <IconBlueFile width={14} height={18} />,
          type: ActionType.history,
        },
      ];
    case StatusNotification.processing:
      return [
        {
          name: 'eContract.NT.TxtPriority',
          icon: <IconPriority width={18} height={18} />,
          type: ActionType.priority,
        },
        {
          name: 'eContract.NT.TxtOpenDocument',
          icon: <IconBlueFile width={14} height={18} />,
          type: ActionType.open,
        },
        {
          name: 'eContract.NT.TxtHistory',
          icon: <IconBlueFile width={14} height={18} />,
          type: ActionType.history,
        },
        {
          name: 'eContract.NT.TxtAuthority',
          icon: <IconAuthority width={23} height={18} />,
          type: ActionType.authority,
        },
        {
          name: 'eContract.NT.TxtForward',
          icon: <IconForward width={18} height={18} />,
          type: ActionType.forward,
        },
      ];
    default:
      return [];
  }
};

