import {DrawerActions, useNavigation} from '@react-navigation/native';
import React, {useState} from 'react';
import {useTranslation} from 'react-i18next';
import {
  Keyboard,
  TextInput,
  TouchableOpacity,
  View,
  ViewStyle,
} from 'react-native';
import styles from './styles';
import {isEmpty} from 'lodash';
import {useDocumentStore} from '../../../../../navigation/SideMenu/store/app-store';
import {ItemType} from '../../../../../navigation/SideMenu/components/CustomDrawerContent/helper';
import {
  IconBlackClose,
  IconBlackDraw,
  IconGreyFilter,
  IconGreySearch,
} from '../../../../../assets/images';
import {Color, NavigationName} from '../../../../../constants';

type Props = {
  searchText: string;
  setSearchText: (text: string) => void;
  onPressFilter: () => void;
  showIconDraw?: boolean;
  containerStyle?: ViewStyle;
  styleTextInput?: ViewStyle;
  isFilter?: boolean;
  placeholder?: string;
};

const InputSearch = ({
  searchText,
  setSearchText,
  onPressFilter,
  showIconDraw = true,
  containerStyle,
  styleTextInput,
  isFilter = true,
  placeholder,
}: Props) => {
  const {t} = useTranslation();
  const navigation = useNavigation<any>();

  const currentFocused = useDocumentStore(state => state.currentFocused);

  const [isFocused, setIsFocused] = useState(false);

  const onOpenDraw = () => {
    Keyboard.dismiss();
    navigation.navigate(NavigationName.CustomDrawerContent);
  };

  const onPressIconRight = () => {
    if (!isFocused || isEmpty(searchText)) {
      onPressFilter();
    }
    setSearchText('');
  };

  const renderIconFilter = () => {
    if (currentFocused === ItemType.TemplateShare) {
      return null;
    }
    return <IconGreyFilter width={16} height={16} />;
  };

  return (
    <View style={[styles.container, containerStyle]}>
      {showIconDraw && (
        <TouchableOpacity style={styles.icon} onPress={onOpenDraw}>
          <IconBlackDraw width={16} height={16} />
        </TouchableOpacity>
      )}
      <View
        style={[
          styles.viewInput,
          styleTextInput,
          isFocused && {borderColor: Color.Primary},
        ]}>
        <IconGreySearch width={16} height={16} />
        <TextInput
          allowFontScaling={false}
          value={searchText}
          style={styles.textInput}
          placeholder={placeholder || t('eContract.DC.TxtSearch')}
          placeholderTextColor={'#667085'}
          onChangeText={setSearchText}
          onFocus={() => setIsFocused(true)}
          onBlur={() => setIsFocused(false)}
        />
        <TouchableOpacity style={styles.btnFilter} onPress={onPressIconRight}>
          {!isFocused || isEmpty(searchText) ? (
            isFilter ? (
              renderIconFilter()
            ) : null
          ) : (
            <IconBlackClose width={16} height={16} />
          )}
        </TouchableOpacity>
      </View>
    </View>
  );
};

export default InputSearch;
