export const handleDownloadUrl = (id: string) => {
  return `${BASE_URL}/services/envelope/api/envelope/${id}/doc/contentall`;
};

export const isShowRelatedDocument = (type: ItemType) => {
  switch (type) {
    case ItemType.Inprogress:
    case ItemType.Done:
    case ItemType.SignFlow:
    case ItemType.CCDocument:
      return true;

    default:
      return false;
  }
};

export const getNumRelatedDocument = (data: {documents: any[]}) => {
  return data.documents.filter(item => item.type === 'ATTACHED').length || 0;
};
