import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {SafeAreaView} from 'react-native-safe-area-context';
import ConfigItem from './components/ConfigItem';
import ModalConfigPassword from './components/ModalConfigPassword';
import ModalHistoryPassword from './components/ModalHistoryPassword';
import {IConfigPassword, isValueInEnum, LIST_CONFIG_PASSWORD} from './helper';
import styles from './styles';
import {ScrollView} from 'react-native';
import {useAppDispatch} from '../../../hook/useRedux';
import {IPasswordConfig} from '../../../services/interface';
import {useGeneralSettingServices} from '../../../hook/apiHook/useApi';
import Toast from 'react-native-toast-message';
import HeaderCM from '../../../components/Header/HeaderCM';
import {IconBluePublished} from '../../../assets/images';
import {View as ViewCM} from 'react-native';
import {SizeDP} from '../../../constants/Size';
import TextCM from '../../../components/Text';

const ConfigSecurityPassword = () => {
  const {t} = useTranslation();
  const generalSettingServices = useGeneralSettingServices();

  const [showModalConfig, setShowModalConfig] = useState(false);

  const [showModalHistory, setShowModalHistory] = useState(false);

  const [current, setCurrent] = useState<any>();

  const [data, setData] = useState<IPasswordConfig[]>([]);

  const [selected, setSelected] = useState(false);

  const toggleModalConfig = () => {
    setShowModalConfig(!showModalConfig);
  };

  const toggleModalHistory = () => {
    setShowModalHistory(!showModalHistory);
  };

  const toggleSelected = () => {
    setSelected(!selected);
  };

  useEffect(() => {
    getData();
  }, []);

  const getData = async () => {
    try {
      const res = await generalSettingServices.getSecurityPasswordConfig();
      const filterData = res.filter(
        (item: any) =>
          item.type === 'password' &&
          item.custId !== 0 &&
          isValueInEnum(item.configType, IConfigPassword),
      );
      if (filterData.length > 0) {
        setData(filterData);
      } else {
        setData(
          res.filter(
            (item: any) =>
              item.type === 'password' &&
              item.custId === 0 &&
              isValueInEnum(item.configType, IConfigPassword),
          ),
        );
      }
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('eContract.CM.TxtSystemError'),
      });
    }
  };

  const onSubmitEdit = async (type: IConfigPassword, editAttr: any) => {
    try {
      const res = await generalSettingServices.editSecurityPasswordConfig(
        data.map(item => {
          if (item.configType === type) {
            return {
              ...item,
              ...editAttr,
            };
          }
          return item;
        }),
      );
      setData(res);
      toggleModalConfig();
      Toast.show({
        type: 'success',
        text1: t('eContract.GS.configSuccess'),
      });
    } catch (error) {}
  };

  const onPressEdit = (item: IPasswordConfig) => () => {
    toggleModalConfig();
    setCurrent(item);
  };

  const onPressCard = (item: IPasswordConfig) => () => {
    toggleModalHistory();
    setCurrent(item);
  };

  const onPressSwitch = (item: IPasswordConfig) => async () => {
    try {
      const findIndex = data.findIndex(i => i.configType === item.configType);
      data[findIndex].status = !item.status;
      const res = await generalSettingServices.editSecurityPasswordConfig(data);
      setData(res);
      Toast.show({
        type: 'success',
        text1: t('eContract.GS.configSuccess'),
      });
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('eContract.CM.TxtSystemError'),
      });
    }
  };

  return (
    <SafeAreaView edges={['bottom']} style={styles.container}>
      <HeaderCM title={`${t('eContract.GS.configSecurity')} - ${t('eContract.GS.password')}`} />
      <ViewCM style={styles.body}>
        <ViewCM style={styles.content}>
          <ViewCM style={styles.header}>
            <IconBluePublished width={SizeDP(23)} height={SizeDP(18)} />
            <TextCM style={styles.txtTitle}>{t('eContract.GS.password')}</TextCM>
          </ViewCM>
          <ScrollView contentContainerStyle={{flex: 1, rowGap: SizeDP(16)}}>
            {data.map(item => {
              return (
                <ConfigItem
                  data={item}
                  key={item.configType}
                  onPressCard={onPressCard(item)}
                  onPress={onPressEdit(item)}
                  onPressSwitch={onPressSwitch(item)}
                  label={t(
                    LIST_CONFIG_PASSWORD.find(i => i.type === item.configType)
                      ?.label ?? '',
                  )}
                />
              );
            })}
          </ScrollView>
        </ViewCM>
      </ViewCM>
      {showModalConfig && (
        <ModalConfigPassword
          type={current?.configType}
          onClose={toggleModalConfig}
          isVisible={showModalConfig}
          data={current}
          onSubmit={onSubmitEdit}
        />
      )}
      {showModalHistory && (
        <ModalHistoryPassword
          onClose={toggleModalHistory}
          isVisible={showModalHistory}
          id={current?.id}
        />
      )}
    </SafeAreaView>
  );
};

export default ConfigSecurityPassword;
