import React, {FC, useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {FlatList, TouchableOpacity} from 'react-native';
import {SafeAreaView} from 'react-native-safe-area-context';
import styles from './styles';
import {IItemUtility, IListUtility} from './helper';
import {isEmpty} from 'lodash';
import ModalConfiguration from './components/ModalConfig';
import ModalConfigurationEmail from './components/ModalConfigEmail';
import {useAppSelector} from '../../../hook/useRedux';
import {useGeneralSettingServices} from '../../../hook/apiHook/useApi';
import Toast from 'react-native-toast-message';
import {String} from '../../../constants';
import {IconEditUtility} from '../../../assets/images';
import {SizeDP} from '../../../constants/Size';
import TextCM from '../../../components/Text';
import {View as ViewCM} from 'react-native';
import HeaderCM from '../../../components/Header/HeaderCM';
const AdvancedSetting = () => {
  const {t} = useTranslation();
  const generalSettingServices = useGeneralSettingServices();
  const [data, setData] = useState<IItemUtility[]>();
  const [dataUtilityEdited, setDataUtilityEdited] = useState<IItemUtility[]>();
  const [isModalConfig, setModalConfig] = useState<boolean>(false);
  const [isModalConfigEmail, setModalConfigEmail] = useState<boolean>(false);
  const [itemConfig, setItemConfig] = useState();
  const user = useAppSelector(state => state.account.dataAccount);

  const getListUtility = async () => {
    try {
      const response = await generalSettingServices.getListUtility();
      const responseEdited =
        await generalSettingServices.getListUtilityEdited();
      setData(response);
      setDataUtilityEdited(responseEdited);
    } catch (error) {
      Toast.show({
        text1: t('eContract.CM.errorExist'),
        type: 'error',
      });
    }
  };
  useEffect(() => {
    getListUtility();
  }, []);

  const onCloseModalConfig = () => {
    setModalConfig(false);
  };
  const onShowModalConfig = (item: any) => {
    setItemConfig(item);
    if (item.configType === IListUtility.personalReceiveMail) {
      setModalConfigEmail(true);
    } else {
      setModalConfig(true);
    }
  };

  const onCloseModalConfigEmail = () => {
    setModalConfigEmail(false);
  };
  const onSubmit = async (data: any) => {
    try {
      await generalSettingServices.updateConfigUtility(data);
      Toast.show({
        text1: t('eContract.GS.configSuccess'),
        type: 'success',
      });
      getListUtility();
    } catch (error) {
      Toast.show({
        text1: t('eContract.CM.errorExist'),
        type: 'error',
      });
    }
  };

  const renderTitle = (value: string) => {
    switch (value) {
      case IListUtility.personalConfirmSign:
        return (
          <TextCM numberOfLines={2} style={styles.txtLabel}>
            {t('eContract.GS.defaultAgreeTermsElectronicSigning')}
          </TextCM>
        );
      case IListUtility.personalReceiveMail:
        return (
          <TextCM style={styles.txtLabel}>
            {t('eContract.GS.EmailNotifications')}
          </TextCM>
        );
      case IListUtility.configDateTimeSignImage:
        return (
          <TextCM style={styles.txtLabel}>
            {t('eContract.GS.HidePhotoSignatureDateAndTimeDisplay')}
          </TextCM>
        );
      case IListUtility.configInternalFileAttach:
        return (
          <TextCM style={styles.txtLabel}>
            {t('eContract.GS.DefaultFileAttachmentsInternal')}
          </TextCM>
        );
      default:
        break;
    }
  };

  const renderItem = ({item, index}: {item: IItemUtility; index: number}) => {
    if (
      item.configType === IListUtility.personalConfirmSign ||
      item.configType === IListUtility.personalReceiveMail ||
      item.configType === IListUtility.configDateTimeSignImage ||
      (user?.authorities?.includes(String.ROLE.ROLE_ORG_ADMIN) &&
        item.configType === IListUtility.configInternalFileAttach)
    ) {
      const isEdited = dataUtilityEdited?.some(
        editedItem => editedItem.configType === item.configType,
      );
      const itemEdit: any = dataUtilityEdited?.filter(
        itemEdit => itemEdit.configType === item.configType,
      );

      return (
        <ViewCM key={index} style={styles.ctnItemUtility}>
          {renderTitle(item.configType)}
          <ViewCM style={styles.ctnStatus}>
            {isEdited ? (
              <TextCM style={[styles.txtLabel, styles.txtEdited]}>
                {t('eContract.GS.Edited')}
              </TextCM>
            ) : (
              <TextCM style={[styles.txtLabel, styles.txtNoEdited]}>
                {t('eContract.GS.NotEditedYet')}
              </TextCM>
            )}
            <TouchableOpacity
              onPress={() =>
                onShowModalConfig(!isEmpty(itemEdit) ? itemEdit[0] : item)
              }>
              <IconEditUtility width={SizeDP(32)} height={SizeDP(32)} />
            </TouchableOpacity>
          </ViewCM>
        </ViewCM>
      );
    }
    return null;
  };

  return (
    <SafeAreaView edges={['bottom']} style={styles.container}>
      <HeaderCM title={t('eContract.GS.listOfUtilities')} />
      <FlatList data={data} renderItem={renderItem} />
      <ModalConfiguration
        data={itemConfig}
        isVisible={isModalConfig}
        onClose={onCloseModalConfig}
        onSubmit={onSubmit}
      />
      {isModalConfigEmail && (
        <ModalConfigurationEmail
          data={itemConfig}
          isVisible={isModalConfigEmail}
          onClose={onCloseModalConfigEmail}
          onSubmit={onSubmit}
        />
      )}
    </SafeAreaView>
  );
};

export default AdvancedSetting;
