import {isEmpty} from 'lodash';
import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {ScrollView, TouchableOpacity, View} from 'react-native';
import ModaShowHistory from './components/modalShowHistory';
import {mappingColorByMethod, mappingLabelByMethod} from './helper';
import styles from './styles';
import {IDocument} from '../../../../../model/interface/envelope.interface';
import {useDocumentStore} from '../../../../../navigation/SideMenu/store/app-store';
import {ItemType} from '../../../../../navigation/SideMenu/components/CustomDrawerContent/helper';
import TextCM from '../../../../../components/Text';
import {DateUtils} from '../../../../../utils';
import {
  IconBlackDownArrow,
  IconBlackRightArrow,
} from '../../../../../assets/images';
import {useDocumentServices} from '../../../../../hook/apiHook/useApi';

const HistoryScreen = ({data}: {data: IDocument}) => {
  const {t} = useTranslation();
  const currentFocused = useDocumentStore(state => state.currentFocused);

  //acl_external = chia sẽ
  const [listShared, setlistShared] = useState<any[]>([]);

  //acl_internal = phân quyền
  const [listPermision, setlistPermision] = useState<any[]>([]);

  const DocumentServices = useDocumentServices();

  const getData = async () => {
    try {
      const res = await DocumentServices.getHistory(
        data.id,
        currentFocused === ItemType.MyDocumentTemplate ? 'template' : '',
      );
      setlistShared(
        res
          .filter((item: any) => item.relatedTable === 'acl_external')
          .reverse(),
      );
      setlistPermision(
        res
          .filter((item: any) => item.relatedTable === 'acl_internal')
          .reverse(),
      );
    } catch (error) {}
  };

  useEffect(() => {
    getData();
  }, []);

  return (
    <View style={styles.ctnMain}>
      <ScrollView
        keyboardShouldPersistTaps="handled"
        style={styles.ctnScrollMain}>
        <View style={styles.ctnView}>
          {currentFocused !== ItemType.MyDocumentTemplate ? (
            <>
              <TextCM style={styles.txtTitle}>
                {t('eContract.DC.ShareDocument.label')}
              </TextCM>
              <TextCM style={styles.txtNameDocument}>{data?.name}</TextCM>
            </>
          ) : (
            <TextCM style={styles.txtTitleDocumentTemplate}>
              {t('eContract.DC.ShareDocument.historyShare')}
            </TextCM>
          )}
        </View>
        {currentFocused !== ItemType.MyDocumentTemplate && (
          <CardCollapse
            data={listShared}
            label={t('eContract.DC.ShareDocument.historyShare')}
            type={'share'}
          />
        )}
        <CardCollapse
          data={listPermision}
          label={t('eContract.DC.ShareDocument.historyPermission')}
          type={'permission'}
        />
      </ScrollView>
    </View>
  );
};

export default HistoryScreen;

type Props = {
  label: string;
  data: any[];
  type: 'share' | 'permission';
};

const CardCollapse = ({label, data, type = 'share'}: Props) => {
  const [expand, setExpand] = useState(false);
  const [showModalHisotry, setShowModalHisotry] = useState(false);
  const [currentData, setCurrentData] = useState();
  const currentFocused = useDocumentStore(state => state.currentFocused);

  const toggleExpand = () => {
    setExpand(!expand);
  };
  const toggleModalHisotry = () => {
    setShowModalHisotry(!showModalHisotry);
  };

  const handleOnPress = (item: any) => () => {
    if (type === 'share') {
      setCurrentData(item);
      toggleModalHisotry();
    } else {
      setCurrentData(item);
      toggleModalHisotry();
    }
  };
  if (currentFocused === ItemType.MyDocumentTemplate) {
    return (
      <View style={styles.ctnCardCollapseDocumentTemplate}>
        {!isEmpty(data) && (
          <View style={styles.ctnListItemDocumentTemplate}>
            {data.map((item, index) => {
              return (
                <TouchableOpacity
                  onPress={handleOnPress(item)}
                  key={index}
                  style={styles.ctnItem}>
                  <View style={styles.ctnTopInfo}>
                    <TextCM style={styles.txtItem}>
                      {item?.createdBy ?? ''}
                    </TextCM>
                    {type === 'share' && (
                      <TextCM
                        style={[
                          styles.txtItem,
                          {color: mappingColorByMethod(item?.method)},
                        ]}>
                        {mappingLabelByMethod(item?.method)}
                      </TextCM>
                    )}
                  </View>
                  <TextCM style={styles.txtTime}>
                    {DateUtils.convertDateToDDMMYYYYhhmm(
                      item?.lastModifiedDate,
                    )}
                  </TextCM>
                </TouchableOpacity>
              );
            })}
          </View>
        )}
        <ModaShowHistory
          type={type}
          onClose={toggleModalHisotry}
          isVisible={showModalHisotry}
          data={currentData}
        />
      </View>
    );
  }
  return (
    <View style={styles.ctnCardCollapse}>
      <TouchableOpacity onPress={toggleExpand} style={styles.ctnLabelCollapse}>
        <TextCM style={styles.txtLabelCollapse}>{label}</TextCM>
        {expand ? (
          <IconBlackDownArrow width={16} height={16} />
        ) : (
          <IconBlackRightArrow width={16} height={16} />
        )}
      </TouchableOpacity>
      {expand && !isEmpty(data) && (
        <View style={styles.ctnListItem}>
          {data.map((item, index) => {
            return (
              <TouchableOpacity
                onPress={handleOnPress(item)}
                key={index}
                style={styles.ctnItem}>
                <View style={styles.ctnTopInfo}>
                  <TextCM style={styles.txtItem}>
                    {item?.createdBy ?? ''}
                  </TextCM>
                  {type === 'share' && (
                    <TextCM
                      style={[
                        styles.txtItem,
                        {color: mappingColorByMethod(item?.method)},
                      ]}>
                      {mappingLabelByMethod(item?.method)}
                    </TextCM>
                  )}
                </View>
                <TextCM style={styles.txtTime}>
                  {DateUtils.convertDateToDDMMYYYYhhmm(item?.lastModifiedDate)}
                </TextCM>
              </TouchableOpacity>
            );
          })}
        </View>
      )}
      <ModaShowHistory
        type={type}
        onClose={toggleModalHisotry}
        isVisible={showModalHisotry}
        data={currentData}
      />
    </View>
  );
};
