import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {KeyboardAwareScrollView} from 'react-native-keyboard-aware-scroll-view';
import styles from './styles';
import {isEmpty} from 'lodash';
import {getPayloadSignDozen} from './helper';
import {View} from 'react-native';
import BottomSheetCM from '../../../../../components/BottomSheet';
import {
  useCreateNotiServices,
  useGeneralSettingServices,
} from '../../../../../hook/apiHook/useApi';
import TextCM from '../../../../../components/Text';
import ButtonCM from '../../../../../components/Button';
import {EyesIcon, EyesIconOpen} from '../../../../../assets/images';
import Toast from 'react-native-toast-message';
import {useAppSelector} from '../../../../../hook/useRedux';
import useStoreNoti from '../../../store/store';
import TextFieldCM from '../../../../../components/TextField';

type Props = {
  isVisible: boolean;
  onClose: () => void;
};

const ModalInfoCA = ({isVisible, onClose}: Props) => {
  const {t} = useTranslation();
  const {currentSignDozens} = useStoreNoti();

  const is2Tep = () => {
    const lsSignImage = currentSignDozens.filter(i => i.inputSignType === '1');
    const lsSign2 = currentSignDozens.filter(i => i.inputSignType === '3');
    return !isEmpty(lsSignImage) || !isEmpty(lsSign2);
  };

  return (
    <View>
      <BottomSheetCM
        styleBody={styles.container}
        onClose={onClose}
        isVisible={isVisible}
        title={
          is2Tep()
            ? `2. ${t('eContract.LG.notification.TitleCECAsupplier')}`
            : t('eContract.LG.notification.TitleCECAsupplier')
        }
        renderContent={<Content onClose={onClose} />}
      />
    </View>
  );
};

const Content = ({onClose}: {onClose: () => void}) => {
  const {t} = useTranslation();
  const {id} = useAppSelector(state => state.account.dataAccount);

  const {
    currentSignDozens,
    reLoadDataNotification,
    imageSignature,
    setCurrentSignDozens,
    setReloadDataNotification,
  } = useStoreNoti();
  const NotificationServices = useCreateNotiServices();
  const GeneralSettingServices = useGeneralSettingServices();

  const [valueData, setValueData] = useState({
    account: '',
    password: '',
  });

  const [errors, setErrors] = useState<{[key: string]: string}>({});

  useEffect(() => {
    getData();
  }, []);

  const getData = () => {
    GeneralSettingServices.getListDigitalCertificate(id || 0)
      .then(res => {
        setValueData(prev => ({
          ...prev,
          account: res[0]?.agreementUuid,
        }));
      })
      .catch((err: any) => {
        Toast.show({
          type: 'error',
          text1: t('eContract.CM.errorExist'),
        });
      })
      .finally(() => {
        // dispatch(commonActions.setLoading(false));
      });
  };

  const onSubmit = async () => {
    try {
      await NotificationServices.putProcessing(
        currentSignDozens.map(item => item.id),
      );
      const lsCAPass = currentSignDozens.filter(i => i.inputSignType === '2');
      const lsSign2 = currentSignDozens.filter(i => i.inputSignType === '3');
      const lsNo = currentSignDozens.filter(i => i.inputSignType === '0');

      const lsSignImage = currentSignDozens.filter(
        i => i.inputSignType === '1',
      );
      const bodyNo = lsNo.map(item =>
        getPayloadSignDozen(item, null, null, null),
      );

      const bodySignImage = lsSignImage.map(item =>
        getPayloadSignDozen(item, null, null, imageSignature),
      );

      const bodySign2 = lsSign2.map(item =>
        getPayloadSignDozen(
          item,
          valueData.account,
          valueData.password,
          imageSignature,
        ),
      );

      const bodyCAPass = lsCAPass.map(item =>
        getPayloadSignDozen(item, valueData.account, valueData.password, null),
      );
      await NotificationServices.signDozen([
        ...bodyCAPass,
        ...bodyNo,
        ...bodySignImage,
        ...bodySign2,
      ]);
      setCurrentSignDozens([]);
      setReloadDataNotification(!reLoadDataNotification);
      Toast.show({
        type: 'success',
        text1: t('eContract.NT.message.successSignDozen'),
      });
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('eContract.CM.TxtSystemError'),
      });
    } finally {
      onClose();
    }
  };

  const isDisabledButton =
    valueData.account === '' || valueData.password === '';

  const handleChangeText = (type: 'account' | 'password', value: string) => {
    setValueData(prev => ({
      ...prev,
      [type]: value,
    }));
  };

  return (
    <View style={styles.ctn}>
      <TextCM>{t('eContract.LG.notification.CECAsupplier')}</TextCM>
      <KeyboardAwareScrollView style={styles.viewBody}>
        <View style={styles.groupTextCtn}>
          <YupTextField
            controlName={'account'}
            label={t('eContract.LG.notification.accountName')}
            onChangeText={handleChangeText}
            value={valueData.account}
            error={errors['account']}
          />
          <YupTextField
            controlName={'password'}
            label={t('eContract.LG.PasswordPlaceholder')}
            isPasswordField={true}
            onChangeText={handleChangeText}
            value={valueData.password}
            error={errors['password']}
          />
        </View>
      </KeyboardAwareScrollView>
      <ButtonCM
        disabled={isDisabledButton}
        label={t('eContract.CM.BtnConfirm')}
        onPress={onSubmit}
      />
    </View>
  );
};

type TextFieldProps = {
  controlName: string;
  label: string;
  isRequired?: boolean;
  maxLength?: number;
  isPasswordField?: boolean;
  value: string;
  onChangeText: (type: any, value: string) => void;
  error: any;
};

const YupTextField = ({
  label,
  isRequired,
  maxLength,
  isPasswordField = false,
  value,
  onChangeText,
  error,
  controlName,
}: TextFieldProps) => {
  const [isSecureText, setIsSecureText] = useState<boolean>(isPasswordField);

  const renderSecurity = () => {
    if (!isPasswordField) return undefined;
    return isSecureText ? (
      <EyesIcon width={24} height={24} />
    ) : (
      <EyesIconOpen width={24} height={24} />
    );
  };

  return (
    <View>
      <TextFieldCM
        label={label}
        placeholder={label}
        isRequired={isRequired}
        value={value}
        onChangeText={text => onChangeText(controlName, text)}
        secureTextEntry={isSecureText}
        onIconPress={() => setIsSecureText(!isSecureText)}
        maxLength={maxLength}
        errorMessage={error}
        viewIconRight={renderSecurity()}
      />
    </View>
  );
};

export default ModalInfoCA;
