import React, {useCallback, useEffect, useState} from 'react';
import {SafeAreaView, useSafeAreaInsets} from 'react-native-safe-area-context';
import styles from './styles';
import {useTranslation} from 'react-i18next';
import Picker from '../../document-share/tabScreens/shareScreen/components/Picker';
import {useNavigation, useRoute} from '@react-navigation/native';
import {FlatList, KeyboardAvoidingView, View} from 'react-native';
import PicDateView from '../../document-list/components/ModalFilter/components/PicDateView';
import {isEmpty} from 'lodash';
import CheckboxCM from '../../../../components/Checkbox';
import TextCM from '../../../../components/Text';
import {
  IDocTypes,
  IFieldsByHeader,
} from '../../../../model/interface/envelope.interface';
import {NavigationName} from '../../../../constants';
import HeaderCM from '../../../../components/Header/HeaderCM';
import ButtonCM from '../../../../components/Button';
import {useDocumentServices} from '../../../../hook/apiHook/useApi';
import TextFieldCM from '../../../../components/TextField';

const Item = ({item, onChange, error, onBlur}: any) => {
  const {t} = useTranslation();
  const [fromDate, setFromDate] = useState(
    item.value ? new Date(item.value) : new Date(),
  );
  const onChangeFromDate = useCallback((date: any, item: any) => {
    setFromDate(date);
    onChange(item.id, date);
  }, []);

  return (
    <View style={styles.ctnItemDynamic}>
      {item.type === 'Boolean' ? (
        <View style={styles.ctnCheckbox}>
          <CheckboxCM
            checked={item.value === 'true' ? true : false}
            onChange={() =>
              onChange(item.id, item.value === 'true' ? 'false' : 'true')
            }
          />
          <TextCM>{item.name}</TextCM>
        </View>
      ) : item.type === 'Date' ? (
        <PicDateView
          label={item.name}
          date={fromDate}
          onChangeDate={(date: any) => onChangeFromDate(date, item)}
        />
      ) : (
        <TextFieldCM
          isRequired={item.required}
          label={item.name}
          onBlur={onBlur}
          value={item.value}
          placeholder={item.name}
          onChangeText={text => onChange(item.id, text)}
          errorMessage={error && `${t('eContract.CM.RequireField')}`}
        />
      )}
    </View>
  );
};
const GeneralInfomationScreen = () => {
  const {t} = useTranslation();
  const navigation = useNavigation<any>();
  const route = useRoute<any>();
  const dataRoute: any = route.params.data;
  const [dataDynamicItem, setDataDynamicItem] = useState<IFieldsByHeader[]>(
    dataRoute?.header?.fields?.filter(
      (item: any) => item.id !== 'envSubmittedFrom' && item.type !== 'Base64',
    ),
  );
  const [formData, setFormData] = useState(dataDynamicItem);
  const [nameDocType, setNameDocType] = useState<string>();
  const [loadingSubmit, setLoadingSubmit] = useState<boolean>(false);
  const [errors, setErrors] = useState<any>({});

  const DocumentServices = useDocumentServices();

  const getDetailDocument = async () => {
    if (dataRoute.docTypeCode !== null) {
      const res: IDocTypes = await DocumentServices.getDocTypes(
        dataRoute.docTypeCode,
      );
      const newData = res?.fields?.filter(
        (item: any) => item.id !== 'envSubmittedFrom' && item.type !== 'Base64',
      );
      setFormData(
        formData.map(item => {
          const CheckItem = newData.find(i => i.id === item.id);
          return CheckItem ? {...item, required: CheckItem.required} : item;
        }),
      );
      setNameDocType(res.name);
    } else {
      setNameDocType(t('eContract.DC.DocumentsNotThreaded'));
    }
  };

  useEffect(() => {
    getDetailDocument();
  }, []);

  const handleChange = useCallback((id: string, value: any) => {
    setFormData(prevData =>
      prevData.map(item => (item.id === id ? {...item, value} : item)),
    );
    if (errors[id]) {
      setErrors((prevErrors: any) => ({...prevErrors, [id]: false}));
    }
  }, []);

  const onBlur = () => {
    let hasError = false;
    let newErrors: any = {};
    formData.forEach((item: any) => {
      if (item.required && !item.value) {
        hasError = true;
        newErrors[item.id] = true;
      }
    });
    if (hasError) {
      setErrors(newErrors);
    } else {
      setErrors(newErrors);
    }
  };

  const onSubmit = async () => {
    setLoadingSubmit(true);
    const dataFormUpdate = formData.map(form => ({
      id: form.id,
      type: 'header_fields',
      value:
        form.type === 'Date' && !form.value
          ? new Date().toISOString()
          : form.value,
    }));
    navigation.navigate(NavigationName.IdentifySignatoryScreen, {
      data: dataRoute,
      templateId: dataRoute.id,
      dataFormUpdate: dataFormUpdate,
    });
    setLoadingSubmit(false);
  };

  const insets = useSafeAreaInsets();

  return (
    <SafeAreaView edges={['bottom']} style={styles.ctnMain}>
      <KeyboardAvoidingView
        style={{flex: 1}}
        behavior={'padding'}
        keyboardVerticalOffset={-insets.bottom}>
        <HeaderCM title={t('eContract.DC.DocumentTemplate.TxtCreateSingle')} />
        <View style={styles.contain}>
          <View style={styles.body}>
            <TextCM style={styles.txtTitle}>{t('eContract.DC.TxtGeneralInfo')}</TextCM>
            <Picker
              type="inactive"
              value={nameDocType}
              label={t('eContract.HM.TxtDocumentType')}
              onPress={() => {}}
              isRequired
              viewIconRight={null}
            />
            <FlatList
              showsVerticalScrollIndicator={false}
              data={formData}
              keyExtractor={item => item.id}
              renderItem={({item}) => (
                <Item
                  item={item}
                  onChange={handleChange}
                  error={errors[item.id]}
                  onBlur={onBlur}
                />
              )}
            />
          </View>
        </View>
      </KeyboardAvoidingView>
      {isEmpty(errors) ? (
        <ButtonCM
          label={t('eContract.CM.BtnContinue')}
          onPress={onSubmit}
          style={styles.ctnButton}
          loading={loadingSubmit}
        />
      ) : (
        <ButtonCM
          disabled={true}
          label={t('eContract.CM.BtnContinue')}
          onPress={onSubmit}
          style={styles.ctnButton}
        />
      )}
    </SafeAreaView>
  );
};

export default GeneralInfomationScreen;
