import {isEmpty} from 'lodash';
import React, {useEffect, useState} from 'react';
import {useTranslation} from 'react-i18next';
import {Image, Modal, TouchableOpacity} from 'react-native';
import {useSafeAreaInsets} from 'react-native-safe-area-context';
import {ModalAddType} from '../..';
import styles from './styles';
import { IImageSignature } from '../../../../../services/interface';
import Toast from 'react-native-toast-message';
import ImageCropPicker from '../../../../../components/ImageCropPicker';
import { IconBlackLeftArrow, IconNoImage } from '../../../../../assets/images';
import { SizeDP } from '../../../../../constants/Size';
import TextCM from '../../../../../components/Text';
import { View as ViewCM } from 'react-native';
import TextFieldCM from '../../../../../components/TextField';
import { String } from '../../../../../constants';
import ButtonCM from '../../../../../components/Button';
import { useAccountServices } from '../../../../../hook/apiHook/useApi';

type Props = {
  isVisible: boolean;
  onClose: () => void;
  type: ModalAddType;
  onSuccess: () => void;
  data?: IImageSignature;
  isNew?: boolean;
};

const ModalAddImageSignature = ({
  isVisible,
  onClose,
  type,
  onSuccess,
  data,
  isNew,
}: Props) => {
  const {t} = useTranslation();
  const insets = useSafeAreaInsets();
  const accountServices = useAccountServices()

  const [name, setName] = useState('');
  const [image, setImage] = useState<any>();

  useEffect(() => {
    if (data) {
      setName(data.name);
    }
  }, []);

  const onPressSave = async () => {
    onClose();
    const formData = new FormData();
    if (!isEmpty(image)) {
      formData.append('file', {
        uri: image.path,
        type: image.mime,
        name: image.path.split('/').pop(),
      } as unknown as Blob);
    }

    formData.append(
      'dto',
      JSON.stringify({name: name.trim(), star: data?.star || isNew}),
    );
    const body: {
      id?: number;
      data: FormData;
    } = {
      data: formData,
    };
    if (data?.id) {
      body.id = data.id;
    }
    try {
      const res = await accountServices.updateImageSignature(body);
      onSuccess();
      Toast.show({
        type: 'success',
        text1:
          type === 'ADD'
            ? t('eContract.AC.successAddImage')
            : t('eContract.AC.successUpdateImage'),
      })
    } catch (error) {
      Toast.show({
        type: 'error',
        text1: t('eContract.CM.TxtSystemError'),
      })
    }
  };

  const onChoiceImage = () => {
    ImageCropPicker.ChoosePhoto({
      includeBase64Enabled: true,
    }).then((res: any) => {
      if (res) {
        if (res.size > 2000000) {
          Toast.show({
            type: 'error',
            text1: t('eContract.AC.TxtAlertMaxImageSize'),
          })
        } else {
          setImage(res);
        }
      }
    });
  };

  return (
    <Modal animationType="fade" transparent visible={isVisible}>
      <ViewCM style={styles.ctnContainer}>
        <ViewCM style={styles.ctnTop} onTouchEnd={onClose} />
        <ViewCM style={[styles.ctnContent, {paddingBottom: insets.bottom}]}>
          <ViewCM style={styles.viewHeader}>
            <TouchableOpacity onPress={onClose}>
              <IconBlackLeftArrow width={SizeDP(14)} height={SizeDP(16)} />
            </TouchableOpacity>
            <TextCM style={styles.txtTitle}>
              {type === 'ADD'
                ? t('eContract.AC.TxtAddImageSignature')
                : t('eContract.AC.TxtEditImageSignature')}
            </TextCM>
            <ViewCM />
          </ViewCM>
          <ViewCM style={styles.body}>
            <TextFieldCM
              isRequired
              value={name}
              onChangeText={setName}
              label={t('eContract.AC.TxtNameImageSignature')}
              maxLength={100}
            />
            <ViewCM style={styles.viewFormPicImage}>
              <ViewCM style={styles.viewImageHeader}>
                <ViewCM style={styles.viewTxtSignatureImage}>
                  <TextCM style={styles.txtSignatureImag}>
                    {t('eContract.AC.TxtSignatureImage')}
                    <TextCM style={styles.txtRed}> * </TextCM>
                  </TextCM>
                  <TextCM style={styles.txtNote}>
                    {t('eContract.AC.TxtMaxImageSize')}
                  </TextCM>
                </ViewCM>
                <TextCM style={styles.txtNote}>
                  {t('eContract.AC.TxtSupportedFormats')}
                </TextCM>
              </ViewCM>
              {!isEmpty(image) || data?.signature ? (
                <ViewCM style={styles.viewImage}>
                  <Image
                    style={styles.styleImage}
                    source={{
                      uri:
                        String.PREFIX_IMG_BASE64 +
                        (image?.data || data?.signature),
                    }}
                  />
                </ViewCM>
              ) : (
                <ViewCM style={styles.viewNoImage}>
                  <IconNoImage width={SizeDP(60)} height={SizeDP(60)} />
                </ViewCM>
              )}

              <TouchableOpacity
                style={styles.btnUploadImage}
                onPress={onChoiceImage}>
                <TextCM style={styles.txtUpload}>
                  {isEmpty(image) ? t('eContract.AC.uploadImage') : t('eContract.AC.TxtReload')}
                </TextCM>
              </TouchableOpacity>
            </ViewCM>

            <ButtonCM
              label={t('eContract.CM.BtnConfirm')}
              onPress={onPressSave}
              disabled={
                (!image?.data && !data?.signature) || isEmpty(name.trim())
              }
            />
          </ViewCM>
        </ViewCM>
      </ViewCM>
    </Modal>
  );
};

export default ModalAddImageSignature;
